def process(fraud_reports_clean, identity_theft_reports_clean) -> pd.DataFrame:
    combined = pd.concat([fraud_reports_clean, identity_theft_reports_clean], ignore_index=True)
    return combined

def process(combined_reports) -> pd.DataFrame:
    density_by_state = combined_reports.groupby('State').agg({
        'Reports per 100K Population': 'sum',
        '# of Reports': 'sum'
    }).reset_index()
    density_by_state = density_by_state.sort_values('Reports per 100K Population', ascending=False)
    return density_by_state
